-- de-duplicate by employee_code (keep last occurrence)
DELETE FROM emp_master_in a USING emp_master_in b
WHERE a.ctid < b.ctid AND a.employee_code = b.employee_code;

UPDATE public.candidates c SET
  mobile = CASE
    WHEN i.mobile IS NULL THEN c.mobile
    WHEN EXISTS (SELECT 1 FROM public.candidates x WHERE x.mobile = i.mobile AND x.id <> c.id) THEN c.mobile
    ELSE i.mobile END,
  gender = COALESCE(i.gender, c.gender),
  date_of_birth = COALESCE(i.date_of_birth::date, c.date_of_birth),
  preferred_joining_date = COALESCE(i.preferred_joining_date::date, c.preferred_joining_date),
  marital_status = COALESCE(i.marital_status, c.marital_status),
  religion = COALESCE(i.religion, c.religion),
  languages = CASE WHEN i.languages IS NOT NULL THEN i.languages::jsonb ELSE c.languages END,
  emergency_contact_name = COALESCE(i.emergency_contact_name, c.emergency_contact_name),
  emergency_contact_mobile = COALESCE(i.emergency_contact_mobile, c.emergency_contact_mobile),
  emergency_contact_relation = COALESCE(i.emergency_contact_relation, c.emergency_contact_relation),
  present_address1 = COALESCE(i.present_address1, c.present_address1),
  present_address2 = COALESCE(i.present_address2, c.present_address2),
  present_city = COALESCE(i.present_city, c.present_city),
  present_district = COALESCE(i.present_district, c.present_district),
  present_state = COALESCE(i.present_state, c.present_state),
  present_country = COALESCE(i.present_country, c.present_country),
  present_pincode = COALESCE(i.present_pincode, c.present_pincode),
  permanent_address1 = COALESCE(i.permanent_address1, c.permanent_address1),
  permanent_address2 = COALESCE(i.permanent_address2, c.permanent_address2),
  permanent_city = COALESCE(i.permanent_city, c.permanent_city),
  permanent_district = COALESCE(i.permanent_district, c.permanent_district),
  permanent_state = COALESCE(i.permanent_state, c.permanent_state),
  permanent_pincode = COALESCE(i.permanent_pincode, c.permanent_pincode),
  aadhaar_number = CASE
    WHEN i.aadhaar_number IS NULL THEN c.aadhaar_number
    WHEN EXISTS (SELECT 1 FROM public.candidates x WHERE x.aadhaar_number = i.aadhaar_number AND x.id <> c.id) THEN c.aadhaar_number
    ELSE i.aadhaar_number END,
  pan_number = COALESCE(i.pan_number, c.pan_number),
  bank_name = COALESCE(i.bank_name, c.bank_name),
  bank_branch = COALESCE(i.bank_branch, c.bank_branch),
  bank_account_number = COALESCE(i.bank_account_number, c.bank_account_number),
  bank_ifsc = COALESCE(i.bank_ifsc, c.bank_ifsc),
  bank_account_holder = COALESCE(i.bank_account_holder, c.bank_account_holder),
  other_info = COALESCE(c.other_info,'{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object(
    'father_name', i.father_name,
    'mother_name', i.mother_name,
    'spouse_name', i.spouse_name,
    'education_level', i.education_level)),
  physical_health = COALESCE(c.physical_health,'{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object(
    'blood_group', i.blood_group,
    'height', i.height,
    'weight', i.weight,
    'chest', i.chest)),
  compliance = COALESCE(c.compliance,'{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object(
    'uan', i.uan,
    'epf_number', i.epf_number,
    'esic_number', i.esic_number)),
  updated_at = now()
FROM emp_master_in i
WHERE c.employee_code = i.employee_code;

COMMIT;
